import { roles, roleModules } from './crm-model.mjs';
const $ = (selector, root = document) => root.querySelector(selector);
const $$ = (selector, root = document) => [...root.querySelectorAll(selector)];
const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money = value => Number(value || 0).toLocaleString('pt-BR',{style:'currency',currency:'BRL'});
const date = value => value ? new Date(String(value).length===10?value+'T12:00:00':value).toLocaleDateString('pt-BR') : '—';
const today = () => new Date().toLocaleDateString('en-CA');
const isoLocal = (value = new Date()) => new Date(value.getTime()-value.getTimezoneOffset()*60000).toISOString().slice(0,16);
const sum = (rows,key='amount') => rows.reduce((n,r)=>n+Number(r[key]||0),0);
const paths={plus:'M12 5v14M5 12h14',search:'m21 21-5-5M19 10a9 9 0 1 1-18 0 9 9 0 0 1 18 0',close:'m6 6 12 12M6 18 18 6',arrow:'M5 12h14m-5-5 5 5-5 5',download:'M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5',upload:'M12 16V3m-5 5 5-5 5 5M4 16v5h16v-5',bell:'M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4',logout:'M9 4H4v16h5m5-13 5 5-5 5M8 12h12',menu:'M4 6h16M4 12h16M4 18h16',check:'m5 12 4 4L19 6',chart:'M4 20V10m8 10V4m8 16v-8',grid:'M3 3h7v7H3zM14 3h7v7h-7zM3 14h7v7H3zM14 14h7v7h-7z',users:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2M13 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0M17 4a4 4 0 0 1 0 8m3 9v-2a4 4 0 0 0-3-4',calendar:'M4 5h16v16H4zM8 2v6m8-6v6M4 11h16',wallet:'M3 5h18v15H3zM15 10h6v5h-6z',edit:'m15 4 5 5M4 20l4-1L21 6l-5-5L3 14z'};
const icon = (name='grid') => `<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.grid}"/></svg>`;
let state, view='dashboard', query='', statusFilter='', ownerFilter='', calendarDate=new Date(), reportStart='', reportEnd='', toastTimer, refreshTimer;
const records = entity => state?.records[entity] || [];
const record = (entity,id) => records(entity).find(r=>r.id===id);
const userName = id => state?.users.find(u=>u.id===id)?.name || 'Sem responsável';
const stageName = id => state.settings.stages.find(s=>s.id===id)?.name || id;
function notify(text,error=false){clearTimeout(toastTimer);$('#toast').textContent=text;$('#toast').className='show'+(error?' error':'');toastTimer=setTimeout(()=>$('#toast').className='',5000);}
async function api(path,method='GET',data){let response;try{response=await fetch('/api'+path,{method,headers:method==='GET'?{}:{'Content-Type':'application/json'},body:data===undefined?undefined:JSON.stringify(data),credentials:'same-origin'});}catch{throw new Error('Sem conexão com o servidor local. Abra o atalho APP ADM e tente novamente.');}const result=await response.json();if(!response.ok){if(response.status===401&&state){state=null;closeModal();await boot();}throw new Error(result.error||'Não foi possível concluir.');}return result;}
function resetLegacy(){try{if(localStorage.getItem('vnkb_migration_v2')==='done')return;for(const key of Object.keys(localStorage))if(key.startsWith('erp_')||key.startsWith('doc_financa_'))localStorage.removeItem(key);for(const key of Object.keys(sessionStorage))if(key.startsWith('erp_'))sessionStorage.removeItem(key);localStorage.setItem('vnkb_migration_v2','done');}catch{/* A migração não depende da disponibilidade do armazenamento do navegador. */}}
async function boot(){clearInterval(refreshTimer);resetLegacy();try{const auth=await api('/auth/status');if(!auth.user){renderAuth(auth.setup);return;}state=await api('/bootstrap');view=location.hash.slice(1)||'dashboard';renderShell();render();refreshTimer=setInterval(async()=>{if(document.hidden||$('#modal').open||view==='settings'||document.activeElement?.matches('input,select,textarea'))return;try{state=await api('/bootstrap');const indicator=$('#connection');if(indicator){indicator.className='online';indicator.textContent='Conectado';}renderContent();}catch{const indicator=$('#connection');if(indicator){indicator.className='online offline';indicator.textContent='Sem conexão';}}},30000);}catch(e){$('#app').innerHTML=`<div class="auth"><section class="auth-story"><h1>Seu negócio.<br>Uma única gestão.</h1></section><section class="auth-form"><div><h2>Servidor indisponível</h2><p>${esc(e.message)}</p><button data-action="retry">Tentar novamente</button></div></section></div>`;}}
function renderAuth(setup){$('#app').innerHTML=`<div class="auth"><section class="auth-story"><img src="/brand.svg" alt="VNKB"><div class="eyebrow">ERP + CRM • GESTÃO INTEGRADA</div><h1>Relacionamentos que crescem.<br>Operações que fluem.</h1><p>Da primeira conversa ao resultado financeiro, acompanhe toda a jornada da sua empresa.</p><div class="pills"><span>Relacionamento</span><span>Vendas</span><span>Operações</span></div></section><section class="auth-form"><form id="auth-form"><div class="eyebrow">VNKB GESTÃO</div><h2>${setup?'Vamos começar?':'Bem-vindo de volta.'}</h2><p>${setup?'Sua base está vazia. Configure a empresa e crie o primeiro administrador para começar.':'Entre para acompanhar seus clientes e sua operação.'}</p><div class="form-error" id="auth-error"></div>${setup?'<div class="field"><label for="businessName">Nome da empresa</label><input id="businessName" name="businessName" required autocomplete="organization"></div><div class="field"><label for="auth-name">Seu nome</label><input id="auth-name" name="name" required autocomplete="name"></div>':''}<div class="field"><label for="auth-email">E-mail</label><input id="auth-email" name="email" type="email" required autocomplete="username"></div><div class="field"><label for="auth-password">Senha ${setup?'(mínimo 10 caracteres)':''}</label><input id="auth-password" name="password" type="password" minlength="${setup?10:1}" maxlength="200" required autocomplete="${setup?'new-password':'current-password'}"></div><button class="primary" type="submit">${setup?'Criar minha área de trabalho':'Entrar no sistema'} ${icon('arrow')}</button><p class="fine">Banco local • Dados compartilhados entre ERP e CRM</p></form></section></div>`;$('#auth-form').onsubmit=async e=>{e.preventDefault();const button=$('button',e.target);button.disabled=true;try{await api('/auth/'+(setup?'setup':'login'),'POST',Object.fromEntries(new FormData(e.target)));await boot();}catch(error){$('#auth-error').textContent=error.message;}finally{button.disabled=false;}};}
const groups=[['RELACIONAMENTO',['leads','clients','companies','opportunities','pipeline']],['VENDAS E ATENDIMENTO',['tasks','events','activities','proposals','orders','tickets','articles','campaigns','automations']],['OPERAÇÃO ERP',['products','suppliers','purchases','movements','receivables','invoices','employees','payroll','vehicles','fleetCosts','contracts','documents']],['GESTÃO',['reports','integrations','settings']]];
const extra={dashboard:{title:'Dashboard',icon:'◫',description:'Uma visão clara dos seus relacionamentos e resultados.'},pipeline:{title:'Funil de Vendas',icon:'▥',description:'Da prospecção ao fechamento. Cada negócio no seu lugar.'},reports:{title:'Relatórios',icon:'▥',description:'Transforme os dados da operação em decisões.'},integrations:{title:'Integrações',icon:'⇄',description:'Conecte seus canais ao fluxo de trabalho.'},settings:{title:'Configurações',icon:'⚙',description:'Sua empresa, equipe e preferências de trabalho.'}};
function allowedView(key){if(key==='settings'||key==='integrations')return state.user.role==='Administrador';if(key==='pipeline')return !!state.modules.opportunities;return !!(state.modules[key]||extra[key]);}
function renderShell(){const name=state.user.name;$('#app').innerHTML=`<div class="layout"><aside class="sidebar"><a href="#dashboard" class="brand"><img src="/brand.svg" alt=""><div><strong>${esc(state.settings.name)}</strong><small>ERP + CRM</small></div></a><div class="workspace-label">${icon('grid')} <span>${esc(state.settings.businessName||'Minha empresa')}</span></div><nav><a href="#dashboard" class="nav-item" data-nav="dashboard">${icon('grid')} Dashboard</a>${groups.map(([label,items],i)=>`<details ${i===2?'':'open'}><summary class="nav-label">${label}</summary>${items.filter(allowedView).map(key=>{const m=state.modules[key]||extra[key];return `<a href="#${key}" class="nav-item" data-nav="${key}"><span class="symbol">${m.icon}</span>${m.title}</a>`;}).join('')}</details>`).join('')}</nav><div class="sidebar-footer"><span class="avatar">${esc(name.slice(0,2).toUpperCase())}</span><div class="person"><strong>${esc(name)}</strong><small>${esc(state.user.role)}</small></div><button class="ghost" data-action="logout" title="Sair" aria-label="Sair">${icon('logout')}</button></div></aside><main class="main"><header class="topbar"><div class="actions"><button class="ghost mobile-menu" data-action="menu" aria-label="Abrir menu">${icon('menu')}</button><span class="breadcrumb">Área de trabalho <span style="margin:0 12px">/</span> <strong id="crumb">Dashboard</strong></span></div><div class="top-actions"><span class="date">${new Date().toLocaleDateString('pt-BR',{day:'numeric',month:'long',year:'numeric'})}</span><span class="online" id="connection">Conectado</span><button class="ghost" data-action="alerts" title="Lembretes" aria-label="Lembretes">${icon('bell')}</button><span class="avatar">${esc(name.slice(0,2).toUpperCase())}</span></div></header><div class="content" id="content"></div></main></div>`;}
function render(){if(!state)return;if(!allowedView(view))view='dashboard';$$('[data-nav]').forEach(el=>{el.classList.toggle('active',el.dataset.nav===view);if(el.dataset.nav===view)el.closest('details')?.setAttribute('open','');});$('#crumb').textContent=(state.modules[view]||extra[view]).title;$('.sidebar')?.classList.remove('open');renderContent();}
function heading(actions=''){const m=state.modules[view]||extra[view];return `<div class="page-head"><div><div class="eyebrow">${['dashboard','reports','settings','integrations'].includes(view)?'GESTÃO INTEGRADA':groups[2][1].includes(view)?'OPERAÇÃO • ERP':'RELACIONAMENTO • CRM'}</div><h1>${m.title}</h1><p>${m.description}</p></div><div class="actions">${actions}</div></div>`;}
function kpi(label,value,caption,type='chart'){return `<div class="kpi"><div class="kpi-label">${label}<span class="kpi-icon">${icon(type)}</span></div><div class="kpi-value">${value}</div><small>${caption}</small></div>`;}
function empty(title,description,entity){return `<div class="empty"><div class="empty-mark">${icon(entity?'plus':'grid')}</div><h3>${title}</h3><p>${description}</p>${entity?`<button class="small" data-new="${entity}">${icon('plus')} Criar primeiro registro</button>`:''}</div>`;}
const badge = value => {const green=['Ativo','Ativa','Pago','Aprovada','Concluída','Concluído','Resolvido','Ganho','Convertido','Recebida','Realizado'];const red=['Perdido','Cancelado','Cancelada','Desqualificado','Recusada','Urgente','Vencido'];const amber=['Pendente','Alta','Em contato','Aguardando cliente','Expirada'];return `<span class="badge ${green.includes(value)?'green':red.includes(value)?'red':amber.includes(value)?'amber':'blue'}">${esc(value||'—')}</span>`;};
function filtered(entity){return records(entity).filter(r=>(!query||Object.values(r).filter(x=>typeof x!=='object').join(' ').toLocaleLowerCase('pt-BR').includes(query.toLocaleLowerCase('pt-BR')))&&(!statusFilter||(r.status||r.stage)===statusFilter)&&(!ownerFilter||r.owner===ownerFilter));}
function renderContent(){if(!state||!$('#content'))return;const target=$('#content');if(view==='dashboard')target.innerHTML=dashboard();else if(view==='pipeline')target.innerHTML=pipeline();else if(view==='events')target.innerHTML=calendar();else if(view==='reports')target.innerHTML=reports();else if(view==='settings'){target.innerHTML=settingsPage();loadSettingsData();}else if(view==='integrations'){target.innerHTML=integrationsPage();loadIntegration();}else target.innerHTML=modulePage(view);associateLabels();}
function dashboard(){const opp=records('opportunities'),open=opp.filter(r=>!['won','lost'].includes(r.stage)),won=opp.filter(r=>r.stage==='won');const tasks=records('tasks').filter(r=>r.status!=='Concluída').sort((a,b)=>a.dueDate.localeCompare(b.dueDate));const revenue=records('receivables').filter(r=>r.type==='Receita'&&r.status==='Pago');const stages=state.settings.stages.filter(s=>!['won','lost'].includes(s.id));const max=Math.max(1,...stages.map(s=>open.filter(o=>o.stage===s.id).length));return heading(`<button data-action="refresh">Atualizar</button>${state.modules.leads?`<button class="primary" data-new="leads">${icon('plus')} Novo lead</button>`:''}`)+`<section class="welcome"><div class="actions" style="flex-wrap:nowrap"><div class="mark">${icon('chart')}</div><div><h2>Bom trabalho, ${esc(state.user.name.split(' ')[0])}.</h2><p>${opp.length||records('clients').length?'Clientes, vendas e operação. Tudo conectado para o seu próximo passo.':'Sua gestão começa aqui. Cadastre um cliente ou lead para iniciar sua jornada.'}</p></div></div>${state.modules.clients?'<button class="small" data-new="clients">Cadastrar cliente →</button>':''}</section><div class="kpis">${kpi('Oportunidades em aberto',money(sum(open)),`${open.length} negociações no funil`)}${kpi('Clientes ativos',records('clients').filter(r=>r.status==='Ativo').length,'Relacionamentos em andamento','users')}${kpi('Receita recebida',money(sum(revenue)),'Recebimentos registrados no financeiro','wallet')}${kpi('Próximas ações',tasks.length,`${tasks.filter(t=>t.dueDate<isoLocal()).length} tarefas com prazo vencido`,'calendar')}</div><div class="grid-2"><section class="panel"><div class="panel-head"><div><h2>Seu funil de vendas</h2><p>Oportunidades por etapa · ${money(sum(open))} em negociação</p></div>${state.modules.opportunities?'<a href="#pipeline">Ver funil →</a>':''}</div><div class="pipeline-bars">${stages.map(s=>{const n=open.filter(o=>o.stage===s.id).length;return `<div class="pipeline-bar"><span>${esc(s.name)}</span><div class="bar-track"><div class="bar-fill" style="width:${n/max*100}%"></div></div><span>${n} negócio${n===1?'':'s'}</span></div>`;}).join('')}</div><div class="table-foot">Previsão ponderada: <strong>${money(open.reduce((n,r)=>n+Number(r.amount||0)*Number(r.probability||0)/100,0))}</strong> · Ganhos: ${won.length}</div></section><section class="panel"><div class="panel-head"><div><h2>Próximas atividades</h2><p>Priorize o que precisa de atenção</p></div>${state.modules.tasks?'<a href="#tasks">Ver todas →</a>':''}</div>${tasks.length?tasks.slice(0,5).map(t=>`<div class="task-line"><button class="small" data-complete="${t.id}" aria-label="Concluir ${esc(t.name)}">${icon('check')}</button><div class="text"><strong>${esc(t.name)}</strong><small>${date(t.dueDate)} · ${esc(userName(t.owner))}</small></div>${t.dueDate<isoLocal()?badge('Vencido'):badge(t.priority)}</div>`).join(''):empty('Tudo em dia por aqui','Adicione um follow-up ou compromisso e acompanhe seus próximos passos.',state.modules.tasks?'tasks':null)}</section></div><section class="panel"><div class="panel-head"><div><h2>Visão da operação</h2><p>ERP e CRM trabalhando juntos</p></div><a href="#reports">Ver relatórios →</a></div><div class="panel-body" style="display:grid;grid-template-columns:repeat(3,1fr);gap:20px"><div><small>Pedidos em execução</small><h2 style="margin-top:10px">${records('orders').filter(r=>!['Concluído','Cancelado'].includes(r.status)).length}</h2></div><div><small>Chamados em aberto</small><h2 style="margin-top:10px">${records('tickets').filter(r=>r.status!=='Resolvido').length}</h2></div><div><small>Saldo realizado</small><h2 style="margin-top:10px">${money(sum(revenue)-sum(records('receivables').filter(r=>r.type==='Despesa'&&r.status==='Pago')))}</h2></div></div></section>`;}
const columns={leads:['name','source','status','score','owner'],clients:['name','phone','segment','owner','status'],companies:['name','document','city','segment','owner'],opportunities:['name','amount','stage','closeDate','owner'],tasks:['name','dueDate','priority','owner','status'],activities:['name','channel','clientId','date','owner'],proposals:['name','clientId','amount','validUntil','status'],orders:['name','clientId','amount','deliveryDate','status'],products:['name','sku','type','price','status'],tickets:['name','clientId','priority','slaDue','status'],articles:['name','category','status'],campaigns:['name','channel','segment','startDate','status'],automations:['name','trigger','days','status'],receivables:['name','type','amount','dueDate','status'],suppliers:['name','document','phone','city'],purchases:['name','supplierId','amount','deliveryDate','status'],movements:['name','productId','type','quantity','date'],invoices:['name','type','amount','date','status'],employees:['name','job','department','salary','status'],payroll:['name','employeeId','month','amount','status'],vehicles:['name','plate','odometer','licenseDate','status'],fleetCosts:['name','vehicleId','type','amount','date'],contracts:['name','clientId','amount','endDate','status'],documents:['name','category','expiryDate','owner']};
function display(entity,key,value){const f=state.modules[entity]?.fields.find(f=>f.key===key);if(key==='owner')return esc(userName(value));if(key==='stage')return badge(stageName(value));if(['status','priority'].includes(key))return badge(value);if(['amount','price','salary','budget','specialPrice','discount'].includes(key))return money(value);if(f?.type==='relation')return esc(record(f.entity,value)?.name||'—');if(f?.type==='date'||f?.type==='datetime-local')return date(value);return esc(value||value===0?value:'—');}
function toolbar(entity){const m=state.modules[entity];const statuses=m.fields.find(f=>f.key==='status')?.options;return `<div class="toolbar"><div class="filters"><div class="search">${icon('search')}<input id="search" aria-label="Pesquisar registros" placeholder="Buscar em ${m.title.toLowerCase()}…" value="${esc(query)}"></div>${statuses?`<select id="status-filter" aria-label="Filtrar status"><option value="">Todos os status</option>${statuses.map(s=>`<option ${statusFilter===s?'selected':''}>${esc(s)}</option>`).join('')}</select>`:''}${m.fields.some(f=>f.key==='owner')?`<select id="owner-filter" aria-label="Filtrar responsável"><option value="">Toda a equipe</option>${state.users.filter(u=>u.active).map(u=>`<option value="${u.id}" ${ownerFilter===u.id?'selected':''}>${esc(u.name)}</option>`).join('')}</select>`:''}</div><span class="muted" style="font-size:11px">${filtered(entity).length} registros</span></div>`;}
function table(entity,rows=filtered(entity)){const m=state.modules[entity],cols=columns[entity]||['name','status'];return rows.length?`<div class="table-wrap"><table><thead><tr>${cols.map(key=>`<th>${m.fields.find(f=>f.key===key)?.label||(key==='amount'?'Valor total':'Registro')}</th>`).join('')}<th></th></tr></thead><tbody>${rows.map(r=>`<tr data-detail="${entity}" data-id="${r.id}" tabindex="0" aria-label="Abrir ${esc(r.name)}">${cols.map((key,i)=>`<td>${display(entity,key,r[key])}${i===0&&r.email?`<span class="sub">${esc(r.email)}</span>`:''}</td>`).join('')}<td>↗</td></tr>`).join('')}</tbody></table></div><div class="table-foot">${rows.length} registros · Clique em uma linha para ver detalhes e histórico.</div>`:empty(query||statusFilter||ownerFilter?'Nenhum resultado encontrado':`Seus registros de ${m.title.toLowerCase()} aparecerão aqui`,query||statusFilter||ownerFilter?'Tente outro termo ou ajuste os filtros.':`Comece adicionando ${m.singular==='empresa'?'uma':'um'} ${m.singular}.`,query||statusFilter||ownerFilter?null:entity);}
function modulePage(entity){const m=state.modules[entity];let intro='';if(entity==='receivables'){const entries=records(entity);intro=`<div class="kpis">${kpi('A receber',money(sum(entries.filter(r=>r.type==='Receita'&&r.status==='Pendente'))),'Receitas pendentes','wallet')}${kpi('A pagar',money(sum(entries.filter(r=>r.type==='Despesa'&&r.status==='Pendente'))),'Despesas pendentes','wallet')}${kpi('Saldo realizado',money(sum(entries.filter(r=>r.type==='Receita'&&r.status==='Pago'))-sum(entries.filter(r=>r.type==='Despesa'&&r.status==='Pago'))),'Recebimentos menos pagamentos')}${kpi('Comissões pagáveis',money(entries.filter(r=>r.type==='Receita'&&r.status==='Pago').reduce((n,r)=>n+Number(r.amount)*Number(r.commission||0)/100,0)),'Sobre receitas recebidas')}</div>`;}if(entity==='movements'){intro=`<section class="panel"><div class="panel-head"><h2>Saldo por produto</h2><a href="#products">Catálogo →</a></div><div class="panel-body">${records('products').filter(p=>p.type==='Produto').map(p=>`<div class="stat-list"><span>${esc(p.name)}</span><strong>${stock(p.id).toLocaleString('pt-BR')}</strong></div>`).join('')||'<p class="muted">Cadastre produtos no catálogo e registre as entradas para iniciar o estoque.</p>'}</div></section>`;}if(entity==='invoices')intro='<div class="note">Este módulo registra documentos emitidos e permite anexar XML/PDF. A emissão fiscal oficial é realizada no provedor fiscal ou portal autorizado da empresa. <a href="https://www.nfse.gov.br/EmissorNacional" target="_blank" rel="noopener">Abrir Emissor Nacional ↗</a></div>';if(entity==='campaigns')intro='<div class="note">Planeje campanhas e públicos por tags. Disparos de e-mail, WhatsApp e anúncios dependem da conexão do provedor em Integrações; o sistema não envia mensagens automaticamente nesta instalação.</div>';if(entity==='payroll')intro='<div class="note">Controle interno de lançamentos de folha. Cálculos trabalhistas, obrigações e transmissão ao eSocial devem ser realizados no sistema contábil responsável.</div>';return heading(`<button data-export="${entity}">${icon('download')} Exportar</button>${['leads','clients','companies','products'].includes(entity)?`<button data-import="${entity}">${icon('upload')} Importar</button>`:''}<button class="primary" data-new="${entity}">${icon('plus')} Adicionar</button>`)+intro+`<section class="panel">${toolbar(entity)}<div id="table-content">${table(entity)}</div></section>`;}
function stock(id){return records('movements').filter(m=>m.productId===id).reduce((n,m)=>n+(m.type==='Entrada'?1:-1)*Number(m.quantity),0);}
function pipeline(){const rows=records('opportunities');return heading('<a href="#opportunities"><button>Ver em lista</button></a><button class="primary" data-new="opportunities">'+icon('plus')+' Nova oportunidade</button>')+`<div class="note">Arraste os cartões entre etapas ou abra uma oportunidade para editar. Negócios perdidos exigem um motivo.</div><div class="board">${state.settings.stages.map(s=>{const deals=rows.filter(r=>r.stage===s.id);return `<section class="kanban-col" data-drop="${esc(s.id)}"><div class="kanban-head"><span class="dot"></span>${esc(s.name)}<small>${deals.length}</small></div><div class="kanban-total">${money(sum(deals))}</div>${deals.map(r=>`<article class="deal" draggable="true" data-drag="${r.id}" data-detail="opportunities" data-id="${r.id}" tabindex="0"><h3>${esc(r.name)}</h3><p>${esc(record('clients',r.clientId)?.name||'Cliente não vinculado')}</p><span class="amount">${money(r.amount)}</span><div class="deal-bottom"><span>${esc(userName(r.owner))}</span><span>${Number(r.probability||0)}%</span></div></article>`).join('')||'<div class="kanban-empty">Nenhum negócio nesta etapa</div>'}</section>`;}).join('')}</div>`;}
function calendar(){const year=calendarDate.getFullYear(),month=calendarDate.getMonth(),first=new Date(year,month,1),offset=(first.getDay()+6)%7,start=new Date(year,month,1-offset);return heading('<button data-action="calendar-export">'+icon('download')+' Exportar agenda</button><button class="primary" data-new="events">'+icon('plus')+' Novo compromisso</button>')+`<section class="panel"><div class="panel-head"><h2>${calendarDate.toLocaleDateString('pt-BR',{month:'long',year:'numeric'})}</h2><div class="actions"><button class="small" data-month="-1" aria-label="Mês anterior">←</button><button class="small" data-month="0">Hoje</button><button class="small" data-month="1" aria-label="Próximo mês">→</button></div></div><div class="calendar">${['SEG','TER','QUA','QUI','SEX','SÁB','DOM'].map(d=>`<div class="weekday">${d}</div>`).join('')}${Array.from({length:42},(_,i)=>{const d=new Date(start);d.setDate(start.getDate()+i);const key=isoLocal(d).slice(0,10);return `<div class="day ${d.getMonth()!==month?'other':''} ${key===today()?'today':''}"><span class="day-number">${d.getDate()}</span>${records('events').filter(e=>e.start.slice(0,10)===key&&e.status!=='Cancelado').map(e=>`<button class="event-chip" data-detail="events" data-id="${e.id}">${esc(e.start.slice(11,16))} ${esc(e.name)}</button>`).join('')}</div>`;}).join('')}</div></section>`;}
function reports(){const inRange=r=>{const d=(r.closedAt||r.paidDate||r.createdAt||'').slice(0,10);return(!reportStart||d>=reportStart)&&(!reportEnd||d<=reportEnd);};const opp=records('opportunities').filter(inRange),won=opp.filter(r=>r.stage==='won'),lost=opp.filter(r=>r.stage==='lost'),entries=records('receivables').filter(inRange),paid=entries.filter(r=>r.status==='Pago'),open=records('opportunities').filter(r=>!['won','lost'].includes(r.stage));const monthly=Array.from({length:6},(_,i)=>{const d=new Date();d.setDate(1);d.setMonth(d.getMonth()-5+i);const key=isoLocal(d).slice(0,7);return {label:d.toLocaleDateString('pt-BR',{month:'short'}),value:sum(won.filter(r=>(r.closedAt||r.updatedAt).slice(0,7)===key))};});const max=Math.max(1,...monthly.map(x=>x.value));return heading('<button data-action="print-report">'+icon('download')+' Imprimir / PDF</button>')+`<div class="panel"><div class="toolbar"><div class="filters"><label>De <input id="report-start" type="date" value="${reportStart}"></label><label>Até <input id="report-end" type="date" value="${reportEnd}"></label><button data-action="report-filter">Aplicar período</button></div><small>Vendas por fechamento; financeiro por pagamento ou criação.</small></div></div><div class="kpis">${kpi('Vendas ganhas',money(sum(won)),`${won.length} negócios fechados`)}${kpi('Taxa de conversão',`${won.length+lost.length?Math.round(won.length/(won.length+lost.length)*100):0}%`,'Ganhos ÷ negócios encerrados')}${kpi('Ticket médio',money(won.length?sum(won)/won.length:0),'Média dos negócios ganhos')}${kpi('Previsão de vendas',money(open.reduce((n,r)=>n+Number(r.amount)*Number(r.probability||0)/100,0)),'Funil aberto atual × probabilidade')}</div><div class="grid-2"><section class="panel"><div class="panel-head"><h2>Vendas nos últimos seis meses</h2></div><div class="report-bars">${monthly.map(x=>`<div class="report-col"><span>${money(x.value)}</span><i style="height:${Math.max(1,x.value/max*100)}px"></i><span>${x.label}</span></div>`).join('')}</div></section><section class="panel"><div class="panel-head"><h2>Caixa realizado no período</h2></div><div class="panel-body"><div class="stat-list"><span>Recebimentos</span><strong>${money(sum(paid.filter(r=>r.type==='Receita')))}</strong></div><div class="stat-list"><span>Pagamentos</span><strong>${money(sum(paid.filter(r=>r.type==='Despesa')))}</strong></div><div class="stat-list"><span>Saldo</span><strong>${money(sum(paid.filter(r=>r.type==='Receita'))-sum(paid.filter(r=>r.type==='Despesa')))}</strong></div></div></section></div><section class="panel"><div class="panel-head"><h2>Performance por responsável</h2></div><div class="table-wrap"><table><thead><tr><th>Responsável</th><th>Ganhos</th><th>Perdidos</th><th>Vendas</th><th>Conversão</th></tr></thead><tbody>${state.users.map(u=>{const w=won.filter(r=>r.owner===u.id),l=lost.filter(r=>r.owner===u.id);return `<tr><td>${esc(u.name)}</td><td>${w.length}</td><td>${l.length}</td><td>${money(sum(w))}</td><td>${w.length+l.length?Math.round(w.length/(w.length+l.length)*100):0}%</td></tr>`;}).join('')}</tbody></table></div></section><section class="panel"><div class="panel-head"><h2>Motivos de perda</h2></div><div class="panel-body">${[...new Set(lost.map(r=>r.lostReason))].map(reason=>`<div class="stat-list"><span>${esc(reason)}</span><strong>${lost.filter(r=>r.lostReason===reason).length}</strong></div>`).join('')||'<p class="muted">Nenhuma perda registrada no período.</p>'}</div></section>`;}
function settingsPage(){return heading()+`<div class="settings-grid"><section class="panel"><div class="panel-head"><h2>Empresa e preferências</h2></div><form id="settings-form" class="panel-body"><div class="form-error"></div><div class="field"><label>Nome da empresa</label><input name="businessName" value="${esc(state.settings.businessName)}" required></div><div class="field"><label>Nome da área de trabalho</label><input name="name" value="${esc(state.settings.name)}" required></div><div class="field"><label>Modelo de condições comerciais</label><textarea name="proposalTerms">${esc(state.settings.proposalTerms)}</textarea></div><label class="check"><input type="checkbox" name="autoAssign" ${state.settings.autoAssign?'checked':''}> Distribuir novos leads entre vendedores automaticamente</label><label class="check"><input type="checkbox" name="captureEnabled" ${state.settings.captureEnabled?'checked':''}> Habilitar captação pela API</label><h3 style="margin-top:24px">Etapas do funil</h3><p class="muted" style="font-size:11px">Nome e probabilidade padrão (%). Ganho e Perdido são etapas finais.</p><div class="stages-editor">${state.settings.stages.map(s=>stageRow(s)).join('')}</div><button type="button" class="small" data-action="add-stage" style="margin-top:12px">+ Adicionar etapa</button><div class="modal-footer"><button class="primary" type="submit">Salvar configurações</button></div></form></section><div><section class="panel"><div class="panel-head"><h2>Equipe e permissões</h2><button class="small" data-action="new-user">+ Usuário</button></div><div id="users-list" class="panel-body">Carregando…</div></section><section class="panel"><div class="panel-head"><h2>Dados e segurança</h2></div><div class="panel-body"><p class="muted" style="font-size:12px">Os registros e anexos ficam no banco local deste computador. Exporte backups regularmente. Senhas e sessões não são incluídas no backup de dados.</p><div class="actions"><button data-action="backup">${icon('download')} Exportar backup</button><button data-action="restore">Restaurar backup</button><button data-action="audit">Ver auditoria</button></div><hr style="border:0;border-top:1px solid #e2e9e5;margin:22px 0"><p class="muted" style="font-size:11px">Zerar remove registros, documentos e histórico. A empresa e os acessos da equipe são mantidos.</p><button class="danger small" data-action="reset">Zerar dados operacionais</button></div></section></div></div>`;}
function stageRow(s){return `<div class="stage-row" data-stage-id="${esc(s.id)}"><input aria-label="Nome da etapa" data-stage-name value="${esc(s.name)}" required><input aria-label="Probabilidade" data-stage-prob type="number" min="0" max="100" value="${s.probability}" ${['won','lost'].includes(s.id)?'readonly':''}><button type="button" class="small" data-remove-stage ${['won','lost'].includes(s.id)?'disabled':''} aria-label="Remover etapa">×</button></div>`;}
let managedUsers=[];
async function loadSettingsData(){try{managedUsers=await api('/users');const el=$('#users-list');if(el)el.innerHTML=managedUsers.map(u=>`<div class="task-line" style="padding:12px 0"><span class="avatar">${esc(u.name.slice(0,2).toUpperCase())}</span><div class="text"><strong>${esc(u.name)}</strong><small>${esc(u.role)} · ${u.active?'Ativo':'Inativo'}</small></div><button class="small" data-user="${u.id}">Editar</button></div>`).join('');}catch(e){notify(e.message,true);}}
const integrations=[['WhatsApp Business','Conversas e automação de mensagens','Requer conta WhatsApp Business Platform, número habilitado e conexão com a API.'],['E-mail e Outlook','Caixa de entrada e envios','Requer conexão OAuth ou provedor de envio. Links de e-mail manual estão disponíveis nos contatos.'],['Google Calendar','Sincronização de compromissos','A agenda pode ser exportada em ICS. Sincronização bidirecional depende de OAuth.'],['Google e Meta Ads','Captação de leads de anúncios','Configure um conector externo para encaminhar os leads à API de captação.'],['Assinatura eletrônica','Assinaturas em propostas e contratos','Requer um provedor de assinatura. Aprovação interna de proposta já está disponível.'],['Fiscal e bancos','Emissão fiscal e conciliação','Dependem dos provedores e contas da empresa. Registros fiscais e financeiros já estão disponíveis.'],['WordPress e APIs','Formulários e sistemas externos','A API de captação recebe leads com chave de acesso. Disponibilize um servidor HTTPS para uso externo.'],['IA e transcrição','Análise avançada e assistentes','Requer provedor de IA e configuração. A qualificação atual é manual, e a previsão usa probabilidades do funil.'],['Mobile e notificações','Acesso em celulares','Interface adaptada a telas pequenas. Acesso remoto, push e aplicativos Android/iOS exigem implantação adicional.']];
function integrationsPage(){return heading()+`<div class="note">Nenhum serviço externo está conectado. As funções locais de ERP e CRM estão disponíveis; as conexões abaixo precisam dos provedores da empresa. Credenciais de serviços não devem ser inseridas em observações ou cadastros.</div><div class="integration-grid">${integrations.map(([name,title,desc],i)=>`<article class="integration"><div class="logo">${['☏','✉','▣','◎','✎','$','⇄','✧','▯'][i]}</div><h3>${name}</h3><span class="badge">Não conectado</span><p style="margin-top:12px">${desc}</p><small>${title}</small></article>`).join('')}</div><section class="panel" style="margin-top:22px"><div class="panel-head"><h2>API de captação de leads</h2><a href="#settings">Configurar →</a></div><div class="panel-body" id="capture-config">Carregando configuração…</div></section>`;}
async function loadIntegration(){try{const config=await api('/integrations');if(!$('#capture-config'))return;$('#capture-config').innerHTML=`${badge(config.captureEnabled?'Ativa':'Pausada')}<p class="muted" style="font-size:12px;margin-top:12px">A chave deve ser usada somente no servidor do conector, nunca em um formulário público. O endereço abaixo funciona neste computador.</p><div class="field"><label>Endpoint POST</label><input readonly value="${esc(config.endpoint)}"></div><details><summary>Exibir chave e exemplo de requisição</summary><pre>${esc(JSON.stringify({method:'POST',url:config.endpoint,headers:{'Content-Type':'application/json','X-Capture-Key':config.captureKey},body:{name:'Nome do lead',email:'email@empresa.com',phone:'',notes:''}},null,2))}</pre></details>`;}catch(e){notify(e.message,true);}}
function modal(title,html){const el=$('#modal');el.innerHTML=`<div class="modal-head"><h2 id="modal-title">${esc(title)}</h2><button class="ghost small" data-action="close" aria-label="Fechar">${icon('close')}</button></div><div class="modal-content">${html}</div>`;associateLabels();if(!el.open)el.showModal();}
function associateLabels(){ $('.field').forEach((field,i)=>{const label=$('label',field),control=$('input,select,textarea',field);if(label&&control){if(!control.id)control.id='control-'+(control.name||i);label.htmlFor=control.id;}});}
function closeModal(){$('#modal').close();}
function fieldHtml(f,value){let control='',options=[];const attrs=`name="${f.key}" id="field-${f.key}" ${f.required?'required':''}`;if(f.type==='select')options=f.options.map(x=>({id:x,name:x}));if(f.type==='stage')options=state.settings.stages;if(f.type==='user')options=state.users.filter(u=>u.active);if(f.type==='relation')options=records(f.entity);if(['select','stage','user','relation'].includes(f.type)){control=`<select ${attrs}><option value="">Selecionar…</option>${options.map(x=>`<option value="${esc(x.id)}" ${String(value)===String(x.id)?'selected':''}>${esc(x.name)}</option>`).join('')}</select>`;}else if(f.type==='textarea')control=`<textarea ${attrs} maxlength="20000">${esc(value)}</textarea>`;else control=`<input ${attrs} type="${f.type}" value="${esc(value)}" ${f.type==='number'?`step="any" min="${f.min??0}" max="${f.max??1e12}"`:'maxlength="500"'}>`;return `<div class="field ${f.type==='textarea'?'full':''}"><label for="field-${f.key}">${f.label}${f.required?' *':''}</label>${control}</div>`;}
function defaults(entity){const result={};for(const f of state.modules[entity].fields){if(f.type==='select')result[f.key]=f.options[0];if(f.type==='user')result[f.key]=state.user.id;if(f.type==='number'&&f.min===0)result[f.key]=0;}if(entity==='opportunities'){result.stage=state.settings.stages[0].id;result.probability=state.settings.stages[0].probability;}if(entity==='proposals')result.terms=state.settings.proposalTerms;if(entity==='events'){result.start=isoLocal();result.end=isoLocal(new Date(Date.now()+3600000));}if(entity==='activities')result.date=isoLocal();if(entity==='tickets')result.slaDue=isoLocal(new Date(Date.now()+24*3600000));return result;}
function edit(entity,id,seed={}){const m=state.modules[entity];if(!m)return;const existing=id?record(entity,id):null;const row=existing||{...defaults(entity),...seed};modal(`${id?'Editar':'Adicionar'} ${m.singular}`,`<form id="record-form" data-entity="${entity}" data-id="${id||''}" data-version="${existing?.version||''}"><div class="form-error"></div><div class="form-grid">${m.fields.map(f=>fieldHtml(f,row[f.key]??'')).join('')}</div>${m.lines?`<h3>Itens do documento</h3><p class="muted" style="font-size:11px">Produto, descrição, quantidade e preço unitário. O total é calculado no servidor.</p><div id="line-items">${(row.items||[{}]).map(item=>lineRow(item)).join('')}</div><button type="button" class="small" data-action="add-line">+ Adicionar item</button><div class="line-total" id="line-total"></div>`:''}<div class="modal-footer"><button type="button" data-action="close">Cancelar</button><button class="primary" type="submit">Salvar ${m.singular}</button></div></form>`);updateTotal();}
function lineRow(item){return `<div class="line-row"><select name="productId" aria-label="Produto do item"><option value="">Item avulso</option>${records('products').filter(p=>p.status==='Ativo'||p.id===item.productId).map(p=>`<option value="${p.id}" ${p.id===item.productId?'selected':''}>${esc(p.name)}</option>`).join('')}</select><input name="description" aria-label="Descrição do item" placeholder="Descrição" value="${esc(item.description||'')}" required><input name="quantity" aria-label="Quantidade" type="number" step="any" min="0.001" value="${item.quantity||1}" required><input name="price" aria-label="Preço unitário" type="number" step="0.01" min="0" value="${item.price??0}" required><button type="button" data-remove-line aria-label="Remover item">×</button></div>`;}
function getLines(){return $$('.line-row').map(el=>({productId:$('[name=productId]',el).value,description:$('[name=description]',el).value,quantity:Number($('[name=quantity]',el).value),price:Number($('[name=price]',el).value)}));}
function updateTotal(){if($('#line-total')){const value=getLines().reduce((n,i)=>n+i.quantity*i.price,0)-Number($('#field-discount')?.value||0);$('#line-total').textContent='Total: '+money(value);}}
async function refresh(){state=await api('/bootstrap');render();}
async function detail(entity,id){const m=state.modules[entity],r=record(entity,id);if(!r)return;modal(r.name,`<div class="actions"><button data-edit="${entity}" data-id="${id}">${icon('edit')} Editar</button>${entity==='leads'&&r.status!=='Convertido'&&state.modules.clients&&state.modules.opportunities?`<button class="primary" data-convert="${id}">Converter em cliente</button>`:''}${entity==='proposals'?`<button data-print="${entity}" data-id="${id}">Imprimir / PDF</button>${r.status==='Aprovada'&&state.modules.orders?`<button data-order="${id}" ${r.generatedOrderId?'disabled':''}>${r.generatedOrderId?'Pedido gerado':'Gerar pedido'}</button>`:''}`:''}${['orders','purchases'].includes(entity)&&state.modules.receivables?`<button data-finance="${entity}" data-id="${id}" ${r.generatedReceivableId||r.generatedPurchasePaymentId?'disabled':''}>${r.generatedReceivableId||r.generatedPurchasePaymentId?'Financeiro gerado':'Gerar financeiro'}</button>`:''}${['orders','purchases'].includes(entity)&&state.modules.movements?`<button data-stock="${entity}" data-id="${id}" ${r.generatedMovementIds?.length?'disabled':''}>${r.generatedMovementIds?.length?'Estoque movimentado':entity==='orders'?'Entregar produtos':'Receber produtos'}</button>`:''}${r.email?`<a href="mailto:${esc(r.email)}"><button type="button">Abrir e-mail ↗</button></a>`:''}${r.phone?`<a href="https://wa.me/${esc(r.phone.replace(/\D/g,'').replace(/^(?!55)(\d{10,11})$/,'55$1'))}" target="_blank" rel="noopener"><button type="button">Abrir WhatsApp ↗</button></a>`:''}<button class="danger" data-delete="${entity}" data-id="${id}">Excluir</button></div><div class="detail-grid">${m.fields.map(f=>`<div class="${f.type==='textarea'?'full':''}"><label>${f.label}</label><p>${display(entity,f.key,r[f.key])}</p></div>`).join('')}</div>${m.lines?`<h3>Itens · versão ${r.version}</h3><div class="table-wrap"><table><thead><tr><th>Descrição</th><th>Quantidade</th><th>Unitário</th><th>Total</th></tr></thead><tbody>${r.items.map(i=>`<tr><td>${esc(i.description)}</td><td>${i.quantity}</td><td>${money(i.price)}</td><td>${money(i.quantity*i.price)}</td></tr>`).join('')}</tbody></table></div><div class="line-total">Desconto: ${money(r.discount)} · Total: ${money(r.amount)}</div>`:''}${['clients','leads'].includes(entity)?`<h3>Relacionamento</h3><div class="actions">${state.modules.activities?`<button data-related="activities" data-parent="${entity}" data-parent-id="${id}">Registrar interação</button>`:''}${state.modules.tasks?`<button data-related="tasks" data-parent="${entity}" data-parent-id="${id}">Criar follow-up</button>`:''}</div><div class="timeline">${['activities','tasks','opportunities','tickets'].flatMap(type=>records(type).filter(x=>x[entity==='clients'?'clientId':'leadId']===id).map(x=>`<div class="timeline-entry"><a href="#${type}">${esc(x.name)}</a><small>${state.modules[type]?.title} · ${date(x.date||x.dueDate||x.createdAt)}</small></div>`)).join('')||'<p class="muted">Nenhuma interação vinculada.</p>'}</div>`:''}<h3 style="margin-top:25px">Documentos e anexos</h3><div id="attachments">Carregando…</div><label class="check">Anexar arquivo (até 5 MB) <input type="file" id="attachment-input" data-entity="${entity}" data-id="${id}" style="font-size:11px"></label><h3 style="margin-top:25px">Histórico</h3><div id="history">Carregando…</div><div id="revisions"></div>`);try{const history=await api(`/records/${entity}/${id}/history`);if(!$('#history'))return;$('#attachments').innerHTML=history.attachments.map(a=>`<div class="attachment"><a href="/api/attachments/${a.id}" download>${esc(a.name)} ↗</a><small>${Math.ceil(a.size/1024)} KB</small><button class="small danger" data-delete-attachment="${a.id}" data-entity="${entity}" data-id="${id}">Excluir</button></div>`).join('')||'<p class="muted" style="font-size:12px">Nenhum anexo.</p>';$('#history').innerHTML=`<div class="timeline">${history.audit.map(a=>`<div class="timeline-entry">${esc(a.action)} · ${esc(a.userName)}<small>${new Date(a.date).toLocaleString('pt-BR')} · ${esc(a.detail)}</small></div>`).join('')}</div>`;if(history.revisions.length)$('#revisions').innerHTML=`<h3>Versões da proposta</h3>${history.revisions.map(v=>`<details><summary style="padding:10px;cursor:pointer">Versão ${v.version} · ${money(v.data.amount)} · ${esc(v.data.status)}</summary><p>${esc(v.data.terms)}</p>${v.data.items.map(i=>`<p>${esc(i.description)} · ${i.quantity} × ${money(i.price)}</p>`).join('')}</details>`).join('')}`;}catch(e){notify(e.message,true);}}
function userForm(id){const u=managedUsers.find(x=>x.id===id)||{name:'',email:'',role:'Vendedor',active:true,permissions:null};modal(id?'Editar usuário':'Adicionar usuário',`<form id="user-form" data-id="${id||''}"><div class="form-error"></div><div class="form-grid"><div class="field"><label>Nome</label><input name="name" value="${esc(u.name)}" required></div><div class="field"><label>E-mail</label><input name="email" type="email" value="${esc(u.email)}" required></div><div class="field"><label>Perfil</label><select name="role">${roles.map(r=>`<option ${r===u.role?'selected':''}>${r}</option>`).join('')}</select></div><div class="field"><label>${id?'Nova senha (deixe vazio para manter)':'Senha (mínimo 10 caracteres)'}</label><input name="password" type="password" minlength="10" maxlength="200" ${id?'':'required'} autocomplete="new-password"></div></div><label class="check"><input name="active" type="checkbox" ${u.active?'checked':''}> Usuário ativo</label><label class="check"><input name="custom" type="checkbox" ${u.permissions?'checked':''}> Personalizar módulos (administrador sempre tem acesso total)</label><div style="display:grid;grid-template-columns:1fr 1fr;gap:4px">${Object.entries(state.modules).map(([key,m])=>`<label class="check"><input name="permission" type="checkbox" value="${key}" ${(u.permissions||roleModules[u.role]).includes(key)?'checked':''}> ${m.title}</label>`).join('')}</div><div class="modal-footer"><button type="button" data-action="close">Cancelar</button><button class="primary">Salvar usuário</button></div></form>`);}
function download(name,content,type='application/json'){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),30000);}
function csvCell(value){let s=String(value??'');if(/^[=+\-@\t\r]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"';}
function exportCSV(entity){const fields=[...state.modules[entity].fields,...(state.modules[entity].lines?[{key:'amount',label:'Valor total'},{key:'items',label:'Itens'}]:[])];download(`${entity}-${today()}.csv`,'\ufeff'+[fields.map(f=>csvCell(f.label)).join(';'),...filtered(entity).map(r=>fields.map(f=>csvCell(f.type==='relation'?record(f.entity,r[f.key])?.name||'':f.type==='user'?userName(r[f.key]):f.key==='items'?r.items.map(i=>`${i.description} (${i.quantity} x ${i.price})`).join(' | '):r[f.key])).join(';'))].join('\r\n'),'text/csv;charset=utf-8');}
function parseCSV(text){text=text.replace(/^\ufeff/,'');const first=text.split(/\r?\n/)[0];const delimiter=first.includes(';')?';':',';const rows=[];let row=[],cell='',quoted=false;for(let i=0;i<text.length;i++){const c=text[i];if(c==='"'){if(quoted&&text[i+1]==='"'){cell+='"';i++;}else quoted=!quoted;}else if(c===delimiter&&!quoted){row.push(cell);cell='';}else if((c==='\n'||c==='\r')&&!quoted){if(c==='\r'&&text[i+1]==='\n')i++;row.push(cell);if(row.some(x=>x.trim()))rows.push(row);row=[];cell='';}else cell+=c;}if(quoted)throw new Error('CSV contém aspas não fechadas.');row.push(cell);if(row.some(x=>x.trim()))rows.push(row);if(rows.length<2)throw new Error('Inclua cabeçalhos e pelo menos uma linha.');return rows;}
function importForm(entity){modal(`Importar ${state.modules[entity].title.toLowerCase()}`,`<form id="import-form" data-entity="${entity}"><p class="muted">Use o modelo CSV, separado por ponto e vírgula ou vírgula. Máximo de 2.000 linhas. E-mails já cadastrados são ignorados. A importação inteira é cancelada se alguma linha for inválida.</p><div class="form-error"></div><button type="button" class="small" data-template="${entity}">Baixar modelo CSV</button><div class="field" style="margin-top:20px"><label>Arquivo CSV</label><input id="csv-file" type="file" accept=".csv,text/csv"></div><div class="field"><label>Ou cole o conteúdo</label><textarea name="csv" rows="8" placeholder="name;email;phone&#10;"></textarea></div><div class="modal-footer"><button type="button" data-action="close">Cancelar</button><button class="primary">Importar registros</button></div></form>`);}
function exportCalendar(){const escapeICS=s=>String(s||'').replace(/\\/g,'\\\\').replace(/\n/g,'\\n').replace(/;/g,'\\;').replace(/,/g,'\\,');const stamp=s=>new Date(s).toISOString().replace(/[-:]/g,'').replace(/\.\d{3}/,'');const events=records('events').filter(e=>e.status!=='Cancelado');download('agenda-vnkb.ics',['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//VNKB//Gestao//PT-BR',...events.flatMap(e=>['BEGIN:VEVENT',`UID:${e.id}@vnkb.local`,`DTSTAMP:${stamp(new Date())}`,`DTSTART:${stamp(e.start)}`,`DTEND:${stamp(e.end)}`,`SUMMARY:${escapeICS(e.name)}`,`LOCATION:${escapeICS(e.location)}`,`DESCRIPTION:${escapeICS(e.notes)}`,'END:VEVENT']),'END:VCALENDAR'].join('\r\n'),'text/calendar;charset=utf-8');}
function printProposal(id){const r=record('proposals',id),client=record('clients',r.clientId);const win=window.open('','_blank');if(!win){notify('Permita a abertura da janela de impressão.',true);return;}win.document.write(`<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><title>Proposta ${esc(r.name)}</title><style>body{font-family:Arial;color:#234333;margin:50px}h1{font-size:28px}p{line-height:1.6;white-space:pre-wrap}table{width:100%;border-collapse:collapse;margin:30px 0}th,td{text-align:left;border-bottom:1px solid #ddd;padding:12px;font-size:12px}.total{text-align:right;font-size:20px}@media print{button{display:none}}</style></head><body><button onclick="window.print()">Imprimir / salvar PDF</button><p>${esc(state.settings.businessName||state.settings.name)}</p><h1>${esc(r.name)}</h1><p>Cliente: ${esc(client?.name||'Não informado')}<br>Validade: ${date(r.validUntil)} · Versão ${r.version}<br>Status: ${esc(r.status)}</p><table><thead><tr><th>Descrição</th><th>Quantidade</th><th>Preço</th><th>Total</th></tr></thead><tbody>${r.items.map(i=>`<tr><td>${esc(i.description)}</td><td>${i.quantity}</td><td>${money(i.price)}</td><td>${money(i.quantity*i.price)}</td></tr>`).join('')}</tbody></table><p class="total">Subtotal: ${money(r.subtotal)}<br>Desconto: ${money(r.discount)}<br><strong>Total: ${money(r.amount)}</strong></p><h3>Condições comerciais</h3><p>${esc(r.terms)}</p><p>${esc(r.notes)}</p></body></html>`);win.document.close();}
async function alerts(){const tasks=records('tasks').filter(r=>r.status!=='Concluída'&&r.dueDate.slice(0,10)<=today()),tickets=records('tickets').filter(r=>r.status!=='Resolvido'&&r.slaDue<isoLocal()),bills=records('receivables').filter(r=>r.status==='Pendente'&&r.dueDate<today());modal('Central de lembretes',`<p class="muted">Atualizado a cada 30 segundos enquanto o aplicativo está aberto.</p>${[['tasks',tasks],['tickets',tickets],['receivables',bills]].map(([entity,rows])=>rows.map(r=>`<div class="task-line"><div class="text"><strong>${esc(r.name)}</strong><small>${state.modules[entity]?.title} · ${date(r.dueDate||r.slaDue)}</small></div><button class="small" data-detail="${entity}" data-id="${r.id}">Abrir</button></div>`).join('')).join('')||empty('Nenhuma pendência para hoje','Suas tarefas, prazos de atendimento e vencimentos aparecerão aqui.')}`);}
document.addEventListener('submit',async e=>{
 const form=e.target;if(!['record-form','settings-form','user-form','import-form','reset-form','restore-form','lost-form','delete-form'].includes(form.id))return;e.preventDefault();const button=$('button[type=submit],button.primary',form);if(button)button.disabled=true;const error=$('.form-error',form);if(error)error.textContent='';
 try{
  const data=Object.fromEntries(new FormData(form));
  if(form.id==='record-form'){const entity=form.dataset.entity;const input={};for(const f of state.modules[entity].fields)input[f.key]=data[f.key]??'';if(state.modules[entity].lines)input.items=getLines();if(form.dataset.id)input.version=Number(form.dataset.version);await api(`/records/${entity}${form.dataset.id?'/'+form.dataset.id:''}`,form.dataset.id?'PUT':'POST',input);closeModal();await refresh();notify('Registro salvo.');}
  if(form.id==='settings-form'){const stages=$$('.stage-row',form).map(el=>({id:el.dataset.stageId,name:$('[data-stage-name]',el).value,probability:Number($('[data-stage-prob]',el).value)}));await api('/settings','PUT',{...data,stages,autoAssign:!!form.autoAssign.checked,captureEnabled:!!form.captureEnabled.checked});state=await api('/bootstrap');renderShell();render();notify('Configurações salvas.');}
  if(form.id==='user-form'){const input={...data,id:form.dataset.id||undefined,active:form.active.checked,permissions:form.custom.checked?$$('[name=permission]:checked',form).map(el=>el.value):null};await api('/users','POST',input);closeModal();await refresh();notify('Usuário salvo.');}
  if(form.id==='import-form'){let text=data.csv;if($('#csv-file').files[0])text=await $('#csv-file').files[0].text();const [headers,...rows]=parseCSV(text);const entity=form.dataset.entity;const fields=state.modules[entity].fields;const mapped=headers.map(header=>fields.find(f=>f.key.toLowerCase()===header.trim().toLowerCase()||f.label.toLowerCase()===header.trim().toLowerCase()));if(!mapped.some(f=>f?.key==='name'))throw new Error('O CSV deve conter a coluna name ou Nome.');if(mapped.some(f=>!f))throw new Error('Há colunas desconhecidas. Use o modelo disponível.');const input=rows.map((values,i)=>{if(values.length!==headers.length)throw new Error(`Linha ${i+2}: número incorreto de colunas.`);const r=defaults(entity);mapped.forEach((f,j)=>{let v=values[j].trim();if(f.type==='number'&&v)v=v.replace(',','.');if(f.type==='user'&&v){const u=state.users.find(u=>u.id===v||u.name===v);if(!u)throw new Error(`Linha ${i+2}: responsável não encontrado.`);v=u.id;}if(f.type==='relation'&&v){const rel=records(f.entity).find(r=>r.id===v||r.name===v);if(!rel)throw new Error(`Linha ${i+2}: ${f.label} não encontrado.`);v=rel.id;}if(v)r[f.key]=v;});return r;});const result=await api('/import','POST',{entity,rows:input});closeModal();await refresh();notify(`${result.imported} registros importados; ${result.skipped} duplicados ignorados.`);}
  if(form.id==='reset-form'){await api('/reset','POST',data);closeModal();await refresh();notify('Base operacional zerada.');}
  if(form.id==='restore-form'){const file=$('input[type=file]',form).files[0];if(!file)throw new Error('Selecione um backup.');if(file.size>7*1024*1024)throw new Error('Este restaurador aceita backups de até 7 MB. Para bases maiores, use a cópia do banco descrita na documentação.');await api('/restore','POST',{confirmation:data.confirmation,backup:JSON.parse(await file.text())});closeModal();await refresh();notify('Backup restaurado.');}
  if(form.id==='lost-form'){const r=record('opportunities',form.dataset.id);await api('/records/opportunities/'+r.id,'PUT',{...r,stage:'lost',probability:0,lostReason:data.reason});closeModal();await refresh();notify('Etapa atualizada.');}
  if(form.id==='delete-form'){await api(`/records/${form.dataset.entity}/${form.dataset.id}`,'DELETE',{});closeModal();await refresh();notify('Registro excluído.');}
 }catch(err){if(error&&document.contains(error))error.textContent=err.message;else notify(err.message,true);}finally{if(button)button.disabled=false;}
});
document.addEventListener('click',async e=>{
 const el=e.target.closest('button,a,[data-detail]');if(!el)return;
 try{
  if(el.dataset.new){edit(el.dataset.new);return;}
  if(el.dataset.detail){await detail(el.dataset.detail,el.dataset.id);return;}
  if(el.dataset.edit){edit(el.dataset.edit,el.dataset.id);return;}
  if(el.dataset.related){edit(el.dataset.related,null,{[el.dataset.parent==='clients'?'clientId':'leadId']:el.dataset.parentId});return;}
  if(el.dataset.delete){const r=record(el.dataset.delete,el.dataset.id);modal('Excluir registro',`<form id="delete-form" data-entity="${el.dataset.delete}" data-id="${el.dataset.id}"><div class="form-error"></div><p>Excluir <strong>${esc(r.name)}</strong> e seus anexos? A exclusão será bloqueada se existirem outros registros vinculados.</p><div class="modal-footer"><button type="button" data-action="close">Cancelar</button><button class="primary" type="submit">Excluir registro</button></div></form>`);return;}
  if(el.dataset.convert){el.disabled=true;await api(`/records/leads/${el.dataset.convert}/convert`,'POST',{});closeModal();await refresh();notify('Cliente e oportunidade criados.');return;}
  if(el.dataset.order){el.disabled=true;await api(`/records/proposals/${el.dataset.order}/order`,'POST',{});closeModal();await refresh();notify('Pedido gerado com os itens da proposta.');return;}
  if(el.dataset.finance){el.disabled=true;await api(`/records/${el.dataset.finance}/${el.dataset.id}/finance`,'POST',{});closeModal();await refresh();notify('Lançamento criado no financeiro. Revise o vencimento.');return;}
  if(el.dataset.stock){el.disabled=true;await api(`/records/${el.dataset.stock}/${el.dataset.id}/stock`,'POST',{});closeModal();await refresh();notify('Estoque movimentado e documento atualizado.');return;}
  if(el.dataset.complete){const r=record('tasks',el.dataset.complete);await api('/records/tasks/'+r.id,'PUT',{...r,status:'Concluída'});await refresh();notify('Tarefa concluída.');return;}
  if(el.dataset.user){userForm(el.dataset.user);return;}
  if(el.dataset.export){exportCSV(el.dataset.export);return;}
  if(el.dataset.import){importForm(el.dataset.import);return;}
  if(el.dataset.template){const entity=el.dataset.template;const fields=state.modules[entity].fields.filter(f=>!['relation','user'].includes(f.type));download(`modelo-${entity}.csv`,'\ufeff'+fields.map(f=>f.key).join(';')+'\r\n','text/csv;charset=utf-8');return;}
  if(el.dataset.print){printProposal(el.dataset.id);return;}
  if(el.hasAttribute('data-month')){if(el.dataset.month==='0')calendarDate=new Date();else{calendarDate.setDate(1);calendarDate.setMonth(calendarDate.getMonth()+Number(el.dataset.month));}renderContent();return;}
  if(el.hasAttribute('data-remove-line')){el.closest('.line-row').remove();updateTotal();return;}
  if(el.hasAttribute('data-remove-stage')){el.closest('.stage-row').remove();return;}
  if(el.dataset.deleteAttachment){await api('/attachments/'+el.dataset.deleteAttachment,'DELETE',{});await detail(el.dataset.entity,el.dataset.id);notify('Anexo removido.');return;}
  switch(el.dataset.action){
   case'retry':await boot();break;
   case'close':closeModal();break;
   case'menu':$('.sidebar').classList.toggle('open');break;
   case'logout':await api('/auth/logout','POST',{});state=null;await boot();break;
   case'refresh':await refresh();notify('Dados atualizados.');break;
   case'alerts':await alerts();break;
   case'new-user':userForm();break;
   case'add-line':$('#line-items').insertAdjacentHTML('beforeend',lineRow({}));updateTotal();break;
   case'add-stage':$('.stages-editor').insertAdjacentHTML('beforeend',stageRow({id:crypto.randomUUID(),name:'',probability:50}));break;
   case'calendar-export':exportCalendar();break;
   case'print-report':window.print();break;
   case'report-filter':{const start=$('#report-start').value,end=$('#report-end').value;if(start&&end&&start>end)throw new Error('O início deve ser anterior ao fim.');reportStart=start;reportEnd=end;renderContent();break;}
   case'backup':download(`backup-vnkb-${today()}.json`,JSON.stringify(await api('/backup'),null,2));notify('Backup exportado.');break;
   case'audit':{const rows=await api('/audit');modal('Auditoria de ações',`<p class="muted">Últimas 500 ações registradas.</p><div class="timeline">${rows.map(a=>`<div class="timeline-entry"><strong>${esc(a.action)}</strong> · ${esc(a.userName)}<p>${esc(a.detail)}</p><small>${new Date(a.date).toLocaleString('pt-BR')} · ${esc(state.modules[a.entity]?.title||a.entity)}</small></div>`).join('')}</div>`);break;}
   case'reset':modal('Zerar dados operacionais',`<form id="reset-form"><div class="form-error"></div><p>Todos os cadastros, negócios, lançamentos e anexos serão excluídos. Usuários e configurações serão mantidos.</p><div class="field"><label>Digite ZERAR DADOS para confirmar</label><input name="confirmation" required pattern="ZERAR DADOS" autocomplete="off"></div><div class="modal-footer"><button type="button" data-action="close">Cancelar</button><button class="primary" type="submit">Zerar base</button></div></form>`);break;
   case'restore':modal('Restaurar backup',`<form id="restore-form"><div class="form-error"></div><p>Substitui os registros atuais pelo backup desta versão do sistema. Os usuários existentes são mantidos; responsáveis não encontrados ficam sem atribuição. Exporte um backup antes de continuar.</p><div class="field"><label>Arquivo de backup JSON (até 7 MB)</label><input type="file" accept=".json" required></div><div class="field"><label>Digite RESTAURAR para confirmar</label><input name="confirmation" required pattern="RESTAURAR"></div><div class="modal-footer"><button type="button" data-action="close">Cancelar</button><button class="primary" type="submit">Restaurar</button></div></form>`);break;
  }
 }catch(err){notify(err.message,true);el.disabled=false;}
});
document.addEventListener('input',e=>{if(e.target.id==='search'){query=e.target.value;$('#table-content').innerHTML=table(view);}if(e.target.closest('.line-row')||e.target.id==='field-discount')updateTotal();});
document.addEventListener('change',async e=>{try{
 if(e.target.id==='status-filter'||e.target.id==='owner-filter'){statusFilter=$('#status-filter')?.value||'';ownerFilter=$('#owner-filter')?.value||'';$('#table-content').innerHTML=table(view);}
 if(e.target.name==='productId'&&e.target.closest('.line-row')){const p=record('products',e.target.value);if(p){const line=e.target.closest('.line-row');$('[name=description]',line).value=p.name;$('[name=price]',line).value=p.price;updateTotal();}}
 if(e.target.id==='field-stage'){const probability=state.settings.stages.find(s=>s.id===e.target.value)?.probability;$('#field-probability').value=probability??0;}
 if(e.target.name==='role'&&e.target.closest('#user-form')&&!$('#user-form').custom.checked){$$('[name=permission]').forEach(input=>input.checked=roleModules[e.target.value].includes(input.value));}
 if(e.target.id==='attachment-input'){const file=e.target.files[0];if(!file)return;if(file.size>5*1024*1024)throw new Error('O limite por anexo é 5 MB.');const entity=e.target.dataset.entity,id=e.target.dataset.id;const content=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result.split(',')[1]);reader.onerror=reject;reader.readAsDataURL(file);});await api(`/records/${entity}/${id}/attachments`,'POST',{name:file.name,mime:file.type,content});await detail(entity,id);notify('Documento anexado.');}
 }catch(err){notify(err.message,true);}});
document.addEventListener('keydown',e=>{if(e.key==='Enter'&&e.target.matches('[data-detail]')){e.preventDefault();detail(e.target.dataset.detail,e.target.dataset.id);}});
document.addEventListener('dragstart',e=>{const card=e.target.closest('[data-drag]');if(card)e.dataTransfer.setData('text/plain',card.dataset.drag);});
document.addEventListener('dragover',e=>{const col=e.target.closest('[data-drop]');if(col){e.preventDefault();col.classList.add('drag-over');}});
document.addEventListener('dragleave',e=>{const col=e.target.closest('[data-drop]');if(col&&!col.contains(e.relatedTarget))col.classList.remove('drag-over');});
document.addEventListener('drop',async e=>{const col=e.target.closest('[data-drop]');if(!col)return;e.preventDefault();col.classList.remove('drag-over');const r=record('opportunities',e.dataTransfer.getData('text/plain'));if(!r||r.stage===col.dataset.drop)return;const stage=state.settings.stages.find(s=>s.id===col.dataset.drop);if(stage.id==='lost'){modal('Motivo da perda',`<form id="lost-form" data-id="${r.id}"><div class="form-error"></div><div class="field"><label>Por que este negócio foi perdido?</label><textarea name="reason" required></textarea></div><div class="modal-footer"><button type="button" data-action="close">Cancelar</button><button type="submit" class="primary">Registrar perda</button></div></form>`);return;}try{await api('/records/opportunities/'+r.id,'PUT',{...r,stage:stage.id,probability:stage.probability});await refresh();notify('Oportunidade movida.');}catch(err){notify(err.message,true);}});
window.addEventListener('hashchange',()=>{view=location.hash.slice(1)||'dashboard';query='';statusFilter='';ownerFilter='';closeModal();window.scrollTo(0,0);render();});
boot();
